-- 文字列で保存された DateTime 列のうち、Prisma の D1 アダプタの形式 (例: 2026-10-12T00:00:00.123+00:00) と違う値を、同じ時刻のまま揃える。
-- Z 付き、+09:00 などのオフセット付き、秒までの値、空白区切りの CURRENT_TIMESTAMP は、SQLite が同じ時刻の UTC として読む。
-- 読めない文字列は strftime が NULL を返すので書き換えない。正規形の値は一致するので変わらず、再実行しても結果は変わらない。
UPDATE "events" SET "start_date" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "start_date") WHERE typeof("start_date") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "start_date") IS NOT NULL AND "start_date" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "start_date");
UPDATE "events" SET "end_date" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "end_date") WHERE typeof("end_date") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "end_date") IS NOT NULL AND "end_date" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "end_date");
UPDATE "events" SET "ended_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "ended_at") WHERE typeof("ended_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "ended_at") IS NOT NULL AND "ended_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "ended_at");
UPDATE "events" SET "clef_judged_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "clef_judged_at") WHERE typeof("clef_judged_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "clef_judged_at") IS NOT NULL AND "clef_judged_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "clef_judged_at");
UPDATE "events" SET "created_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "created_at") WHERE typeof("created_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "created_at") IS NOT NULL AND "created_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "created_at");
UPDATE "events" SET "updated_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") WHERE typeof("updated_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") IS NOT NULL AND "updated_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at");
