UPDATE "event_conditions" SET "updated_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") WHERE typeof("updated_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") IS NOT NULL AND "updated_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at");
