UPDATE "event_reference_urls" SET "updated_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") WHERE typeof("updated_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") IS NOT NULL AND "updated_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at");
UPDATE "event_stores" SET "created_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "created_at") WHERE typeof("created_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "created_at") IS NOT NULL AND "created_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "created_at");
UPDATE "event_stores" SET "updated_at" = strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") WHERE typeof("updated_at") = 'text' AND strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at") IS NOT NULL AND "updated_at" <> strftime('%Y-%m-%dT%H:%M:%f+00:00', "updated_at");
